16	const AutomationEditor: React.FC = () => {
17	    const {id = ''} = useParams<{id: string}>();
18	
19	    const {data, isLoading: isLoadingAutomation, isError} = useReadAutomation(id, {
20	        defaultErrorHandler: false
21	    });
22	    const automation = data?.automations[0];
23	
24	    const editMutation = useEditAutomation();
25	    const [editState, setEditState] = React.useState<AutomationEditState>('idle');
26	
27	    // Draft is the user-facing, locally mutable copy. The React Query cache stays as server truth;
28	    // staged edits (adding steps, etc.) live here until the user publishes. Seeded once when the
29	    // automation first loads, and reset to the response after every successful edit.
30	    const [draft, setDraft] = React.useState<AutomationDetail | undefined>(undefined);
31	    React.useEffect(() => {
32	        if (automation) {
33	            setDraft((oldDraft) => {
34	                return oldDraft?.id === automation.id ? oldDraft : automation;
35	            });
36	        }
37	    }, [automation]);
38	
39	    // Only compare the fields the user can edit; server-stamped fields like `updated_at` would
40	    // otherwise flip the dirty flag immediately after every successful publish.
41	    const hasUnsavedChanges = !!draft
42	        && !!automation
43	        && !dequal(editableSlice(draft), editableSlice(automation));
44	
45	    const onDraftChange = (next: AutomationDetail) => {
46	        setDraft(next);
47	        setEditState((prev) => {
48	            if (prev === 'failed to save' || prev === 'failed to publish' || prev === 'failed to unpublish') {
49	                return 'idle';
50	            }
51	            return prev;
52	        });
53	    };
54	
55	    const save = (statusToSave?: AutomationStatus) => {
56	        if (!draft) {
57	            throw new Error('Cannot edit an automation that has not loaded.');
58	        }
59	
60	        let errorState: AutomationEditState;
61	        switch (statusToSave) {
62	        case undefined:
63	            setEditState('saving');
64	            errorState = 'failed to save';
65	            break;
66	        case 'active':
67	            setEditState('publishing');
68	            errorState = 'failed to publish';
69	            break;
70	        case 'inactive':
71	            setEditState('unpublishing');
72	            errorState = 'failed to unpublish';
73	            break;
74	        default: {
75	            const _exhaustive: never = statusToSave;
76	            throw new Error(`Unhandled status: ${_exhaustive}`);
77	        }
78	        }
79	        editMutation.mutate(
80	            {
81	                id: draft.id,
82	                status: statusToSave ?? draft.status,
83	                actions: draft.actions,
84	                edges: draft.edges
85	            },
86	            {
87	                onSuccess: (response) => {
88	                    setDraft(response.automations[0]);
89	                    setEditState('idle');
90	                },
91	                onError: () => setEditState(errorState)
92	            }
93	        );
94	    };
95	
96	    let isConfirmUnpublishAlertOpen = false;
97	    let isEditRequestActive = false;
98	    let isSaveButtonEnabled = !!draft && draft.actions.length > 0 && draft.status === 'inactive' && hasUnsavedChanges;
99	    let saveButtonVariant: ButtonProps['variant'] = 'secondary';
100	    let saveButtonChildren: React.ReactNode = 'Save';
101	    let isPublishButtonEnabled = !!draft && draft.actions.length > 0 && (draft.status === 'inactive' || hasUnsavedChanges);
102	    let publishButtonVariant: ButtonProps['variant'] = 'default';
103	    let publishButtonChildren: React.ReactNode = draft?.status === 'active'
104	        ? (hasUnsavedChanges ? 'Publish changes' : 'Published')
105	        : 'Publish';
106	    let isTurnOffButtonEnabled = true;
107	    let turnOffButtonChildren: React.ReactNode = 'Turn off';
108	    switch (editState) {
109	    case 'idle':
110	        break;
111	    case 'saving':
112	        isEditRequestActive = true;
113	        isSaveButtonEnabled = false;
114	        isPublishButtonEnabled = false;
115	        isTurnOffButtonEnabled = false;
116	        saveButtonChildren = (
117	            <>
118	                <LoadingIndicator size='sm' />
119	                <span className='sr-only'>Saving...</span>
120	            </>
121	        );
122	        break;
123	    case 'publishing':
124	        isEditRequestActive = true;
125	        isSaveButtonEnabled = false;
126	        isPublishButtonEnabled = false;
127	        isTurnOffButtonEnabled = false;
128	        publishButtonChildren = (
129	            <>
130	                <LoadingIndicator color='light' size='sm' />
131	                <span className='sr-only'>Publishing...</span>
132	            </>
133	        );
134	        break;
