149	        isConfirmUnpublishAlertOpen = true;
150	        isSaveButtonEnabled = false;
151	        isPublishButtonEnabled = false;
152	        isTurnOffButtonEnabled = false;
153	        break;
154	    case 'failed to save':
155	        saveButtonVariant = 'destructive';
156	        saveButtonChildren = 'Retry';
157	        break;
158	    case 'failed to publish':
159	        publishButtonVariant = 'destructive';
160	        publishButtonChildren = 'Retry';
161	        break;
162	    case 'failed to unpublish':
163	        isConfirmUnpublishAlertOpen = true;
164	        isTurnOffButtonEnabled = true;
165	        turnOffButtonChildren = 'Retry';
166	        break;
